// Additive migration only. No database create/drop/restore or private-file writes.
const fs=require('node:fs'),crypto=require('node:crypto'),cp=require('node:child_process');
const {Pool}=require('/app/node_modules/pg');
const hash=value=>crypto.createHash('sha256').update(value).digest('hex');
const fail=code=>{throw Object.assign(Error(code),{code});};
async function main(){
 const revision=process.env.SOURCE_REVISION,backupId=process.env.EXPECTED_BACKUP_ID,backupHash=process.env.EXPECTED_BACKUP_SHA256;
 if(!/^[a-f0-9]{40}$/.test(revision||'')||!/^[a-f0-9-]{36}$/.test(backupId||'')||!/^[a-f0-9]{64}$/.test(backupHash||''))fail('GPS_MIGRATION_PIN_REQUIRED');
 const s=fs.lstatSync('/private/operator.json');if(process.getuid()!==0||!s.isFile()||s.isSymbolicLink()||s.uid!==0||(s.mode&0o777)!==0o600||s.size>65536)fail('GPS_MIGRATION_OPERATOR_FILE_INVALID');
 const state=JSON.parse(fs.readFileSync('/private/operator.json','utf8'));
 if(typeof state.PG_OWNER_PASSWORD!=='string'||state.PG_OWNER_PASSWORD.length<20||state.PG_OWNER_PASSWORD.includes('\0'))fail('GPS_MIGRATION_OWNER_PASSWORD_INVALID');
 const marker=JSON.parse(fs.readFileSync('/release/PETCORE-RELEASE.json','utf8'));
 if(marker.format!=='petcore.gps.release.v1'||marker.revision!==revision||!marker.unrelated016Absent||marker.volume!=='petcore_gps_20261128')fail('GPS_MIGRATION_RELEASE_MISMATCH');
 const expected=JSON.parse(process.env.MIGRATION_CHECKSUMS||'{}'),files=fs.readdirSync('/app/api/sql').filter(name=>/^\d+_[a-zA-Z0-9_]+\.sql$/.test(name)).sort();
 if(files.length!==24||files.some(name=>name.startsWith('016_'))||JSON.stringify(files)!==JSON.stringify(Object.keys(expected).sort())||files.some(name=>hash(fs.readFileSync('/app/api/sql/'+name))!==expected[name]||marker.migrationChecksums[name]!==expected[name]))fail('GPS_MIGRATION_SOURCE_CHECKSUM_MISMATCH');
 if(fs.existsSync('/app/.env')||hash(fs.readFileSync('/app/api/scripts/migrate.mjs'))!==marker.files['api/scripts/migrate.mjs'])fail('GPS_MIGRATION_RUNNER_MISMATCH');
 const url=new URL('postgresql://petcore_schema_owner@petcore-db:5432/petcore');url.password=state.PG_OWNER_PASSWORD;url.searchParams.set('sslmode','verify-full');url.searchParams.set('sslrootcert','/run/petcore-ca/ca.crt');
 const db=new Pool({connectionString:url.href,max:1,connectionTimeoutMillis:15000,statement_timeout:60000});db.on('error',()=>{});
 const history=async()=>(await db.query('SELECT filename,checksum FROM schema_migrations ORDER BY filename')).rows;
 const tableCount=async()=>(await db.query("SELECT count(*)::int AS n FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p') AND n.nspname='public'")).rows[0].n;
 function checkHistory(rows,n){if(rows.length!==n||rows.some((row,index)=>row.filename!==files[index]||row.checksum!==expected[row.filename]))fail('GPS_MIGRATION_HISTORY_MISMATCH');}
 try{
  const identity=(await db.query("SELECT current_user,current_database(),(SELECT ssl FROM pg_stat_ssl WHERE pid=pg_backend_pid()) AS tls")).rows[0];
  if(identity.current_user!=='petcore_schema_owner'||identity.current_database!=='petcore'||!identity.tls)fail('GPS_MIGRATION_CONNECTION_INVALID');
  const proof=(await db.query("SELECT sha256 FROM backup_runs WHERE id=$1 AND state='uploaded' AND retention_scope='active' AND finished_at>now()-interval '6 hours'",[backupId])).rows[0];if(proof?.sha256!==backupHash)fail('GPS_MIGRATION_RECENT_BACKUP_REQUIRED');
  checkHistory(await history(),23);if(await tableCount()!==58)fail('GPS_MIGRATION_BEFORE_TABLE_COUNT_MISMATCH');
  const defaults=(await db.query("SELECT d.defaclobjtype AS kind,a.privilege_type AS privilege FROM pg_default_acl d JOIN pg_namespace n ON n.oid=d.defaclnamespace JOIN pg_roles owner ON owner.oid=d.defaclrole CROSS JOIN LATERAL aclexplode(d.defaclacl) a JOIN pg_roles grantee ON grantee.oid=a.grantee WHERE n.nspname='public' AND owner.rolname='petcore_schema_owner' AND grantee.rolname='petcore_runtime'")).rows;
  for(const [kind,privileges]of [['r',['SELECT','INSERT','UPDATE','DELETE']],['S',['USAGE','SELECT']]])for(const privilege of privileges)if(!defaults.some(row=>row.kind===kind&&row.privilege===privilege))fail('GPS_MIGRATION_DEFAULT_PRIVILEGES_MISSING');
  const runtime=(await db.query("SELECT rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,has_schema_privilege('petcore_runtime','public','CREATE') AS schema_create FROM pg_roles WHERE rolname='petcore_runtime'")).rows[0];if(!runtime||Object.values(runtime).some(Boolean))fail('GPS_MIGRATION_RUNTIME_ROLE_UNSAFE');
  const env={PATH:process.env.PATH,NODE_ENV:'production',NODE_EXTRA_CA_CERTS:'/run/petcore-ca/ca.crt',DATABASE_SSL:'true',DATABASE_URL:url.href,DATABASE_DIRECT_URL:url.href};
  const child=cp.spawnSync(process.execPath,['/app/api/scripts/migrate.mjs'],{cwd:'/app',env,encoding:'utf8',stdio:['ignore','pipe','pipe'],maxBuffer:1024*1024,timeout:15*60*1000});
  if(child.error||child.status!==0)fail('GPS_MIGRATION_RUNNER_FAILED');
  checkHistory(await history(),24);if(await tableCount()!==59)fail('GPS_MIGRATION_AFTER_TABLE_COUNT_MISMATCH');
  const table=(await db.query("SELECT tableowner,has_table_privilege('petcore_runtime','public.transport_tracking_sessions','SELECT') AS can_select,has_table_privilege('petcore_runtime','public.transport_tracking_sessions','INSERT') AS can_insert,has_table_privilege('petcore_runtime','public.transport_tracking_sessions','UPDATE') AS can_update,has_table_privilege('petcore_runtime','public.transport_tracking_sessions','DELETE') AS can_delete FROM pg_tables WHERE schemaname='public' AND tablename='transport_tracking_sessions'")).rows[0];
  if(table?.tableowner!=='petcore_schema_owner'||!table.can_select||!table.can_insert||!table.can_update||!table.can_delete)fail('GPS_MIGRATION_NEW_TABLE_PRIVILEGES_INVALID');
  console.log(JSON.stringify({ok:true,event:'petcore_gps_migration_verified',revision,migrations:24,tables:59,applied:'025_transport_tracking.sql',checksum:expected['025_transport_tracking.sql'],backupId,backupSha256:backupHash,verifiedTLS:true,defaultPrivilegesVerified:true,runtimeCRUD:{SELECT:true,INSERT:true,UPDATE:true,DELETE:true},unrelated016Absent:true}));
 }finally{await db.end();}
}
main().catch(error=>{console.error(JSON.stringify({ok:false,code:/^GPS_MIGRATION_[A-Z_]+$/.test(error.code||'')?error.code:'GPS_MIGRATION_FAILED'}));process.exitCode=1;});
